import{z as i,x as t,o as E,c as m,q as r,j as s,D as e,d as B,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"内存层次的实践","description":"","frontmatter":{"title":"内存层次的实践","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-memory-hierarchy-practice.md","filePath":"cs/gpu-memory-hierarchy-practice.md","lastUpdated":1791413859000}'),n={name:"cs/gpu-memory-hierarchy-practice.md"};function c(p,a,d,D,h,C){const A=t("Mermaid");return E(),m("div",null,[a[2]||(a[2]=r('<h1 id="内存层次的实践" tabindex="-1">内存层次的实践 <a class="header-anchor" href="#内存层次的实践" aria-label="Permalink to &quot;内存层次的实践&quot;">​</a></h1><div class="epigraph"><p>GPU 的快不是算得快，而是字节恰好停在你正在算的那一层；放错一层的每个字节，都在为带宽排队。</p><footer>—— 据 Kirk &amp; Hwu, Programming Massively Parallel Processors；NVIDIA CUDA C++ Programming Guide 整理</footer></div><p><a href="/cs/gpu-execution-model-deep">上一课</a>把执行合同算到了 warp 调度：延迟隐藏盖得住等待，盖不住没数据可算。一个 warp 停在 long scoreboard 上，等的是哪一层的字节回来，由数据放在哪层决定。本栏的<a href="/cs/gpu-memory-hierarchy">存储层次鸟瞰</a>给过层次图，<a href="/cs/dram-timing">DRAM 时序</a>给过行命中与冲突的账；大模型栏的<a href="/llm/ak-memory-access">内存访问模式分析</a>在注意力内核上算过访存账。本课把这套账写成日常实践：每层的容量与带宽、合并访问的判据、以及「这个数该放哪」的决策规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/roofline-model">roofline</a> 里的 \\(B\\) 到底取哪一层，取决于你把数据钉在哪——算强度的分母随层次变，而初学者几乎总把 HBM 带宽代入，于是把「smem 上的复用没做够」误诊成「带宽墙」。缺口是从层次图到数字的那一步：寄存器、local、shared、L1、L2、HBM 各层的容量与带宽差多少倍，一条全局加载指令在什么条件下折叠成一个事务。没有这张表，优化就是在错误的层上找带宽。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逐层立账（A100 量级）：寄存器每线程私有，访问零等待；超出的变量溢出到 local——名字里有 local，实体在 DRAM，走 L1/L2，这就是溢出比看起来贵得多的原因。shared 是片上 SRAM，与 L1 共用同一块 192 KB 的存储，smem 最多划走 164 KB，分账比例是启动配置。L2 全卡共享，40 MB 量级，是跨 SM 的汇合点。HBM 峰值约 2 TB/s（SXM 型号），容量最大、最远。相邻层的带宽差一到几个数量级：把一个被反复读的量从 HBM 挪进 smem，等价于把它的价格降两个量级。</p><p>合并访问是全局访存的判据：warp 的 32 个地址若落在连续的 128 字节里，硬件折叠成一个事务；地址分散则拆成多个事务，每个事务只用到一部分扇区。判据写代码时就能检查——同一 warp 的第 \\(i\\) 个线程访问 \\(\\mathrm{base}+i\\cdot s\\)：\\(s=1\\) 的 float 数组满宽利用；\\(s=2\\) 有效带宽减半；\\(s\\) 大到每线程独占一个 32 字节扇区时，取回 1024 字节只用 128 字节。<code>__restrict__</code> 与只读声明让编译器敢于走只读通路、省一次 L1 一致性顾虑。</p>',8)),(E(),s(o,null,{default:e(()=>[l(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%85%A8%E5%B1%80%E6%95%B0%E6%8D%AE%E5%9C%A8%20HBM%EF%BC%8C%E7%BA%A6%202%20TB%2Fs%22%5D%20--%3E%20L2%5B%22L2%20%E5%85%A8%E5%8D%A1%E5%85%B1%E4%BA%AB%EF%BC%8C40%20MB%22%5D%0A%20%20L2%20--%3E%20L1%5B%22L1%20%2F%20smem%20%E6%AF%8F%20SM%20%E7%BB%9F%E4%B8%80%20192%20KB%22%5D%0A%20%20L1%20--%3E%20R%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E6%AF%8F%E7%BA%BF%E7%A8%8B%E7%A7%81%E6%9C%89%22%5D%0A%20%20L1%20--%3E%7C%E6%BA%A2%E5%87%BA%EF%BC%9A%E8%B6%85%E9%99%90%E5%8F%98%E9%87%8F%7C%20LOC%5B%22local%EF%BC%9A%E5%AE%9E%E4%BD%93%E5%9C%A8%20DRAM%22%5D%0A%20%20G%20--%3E%7Cstride%20%E5%A4%A7%EF%BC%9A%E5%A4%9A%E4%BA%8B%E5%8A%A1%7C%20WASTE%5B%22%E5%B8%A6%E5%AE%BD%E6%8C%89%E6%89%87%E5%8C%BA%E6%B5%AA%E8%B4%B9%22%5D%0A%20%20G%20--%3E%7Cwarp%20%E8%BF%9E%E7%BB%AD%20128B%7C%20FULL%5B%22%E4%B8%80%E4%B8%AA%E4%BA%8B%E5%8A%A1%E6%BB%A1%E8%BD%BD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合并为什么有效，要接回 <a href="/cs/dram-timing">DRAM 时序</a>：缓存行与扇区是 DRAM 突发长度的镜像，一次请求无论用不用满，行缓冲都按同样粒度服务——分散访问让行缓冲反复换行，把行命中的账换成行冲突的账。smem 与 L1 分账的设计动机也在这：两块用途（程序管理的复用对硬件管理的缓存）对容量与延迟的要求不同，但 SRAM 面积是硬预算，硬件让软件来划这条线——所以 smem 配置是核函数的属性，不是编译期常量。</p><p>放数决策因此有一条固定顺序：先问复用（跨线程共享的量进 smem，warp 内共享的量下一课有更窄的通道），再问合并（全局访问的 stride 与对齐），最后才谈占用率——寄存器用量与占用率的联动在<a href="/llm/cuda-occupancy">占用率课</a>已经算过，本课只提醒一句：为降占用率而省寄存器，省出来的往往是溢出到 local 的流量，账平不了。</p><p><span class="marginnote">数字实例：stride=2 的 float 访问，warp 32 个线程占 256 字节但只用其中一半——有效带宽直接砍半；stride=8 时 32 个线程摊到 1024 字节、只用 128 字节，利用率 12.5%。这不算任何缓存行开销，仅仅是「取回的字节里多少被用到」的账。</span></p><p><span class="marginnote">直觉类比：寄存器是你手边的草稿纸，smem 是小组共用的白板，L2 是全公司档案室，HBM 是城外仓库。手边的纸不要钱，仓库每趟都要派车——把要反复抄的东西搬上白板，比优化车速有效得多。</span></p>',5)),(E(),s(o,null,{default:e(()=>[l(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%8F%98%E9%87%8F%E5%9C%A8%E6%A0%B8%E5%86%85%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20Q%7B%22%E8%83%BD%E5%85%A8%E6%94%BE%E5%AF%84%E5%AD%98%E5%99%A8%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20REG%5B%22%E9%9B%B6%E7%AD%89%E5%BE%85%20%E7%A7%81%E6%9C%89%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%20%E6%95%B0%E7%BB%84%E6%88%96%E5%A4%A7%E7%BB%93%E6%9E%84%22%7C%20SPILL%5B%22%E6%BA%A2%E5%87%BA%20local%20%E5%AE%9E%E4%BD%93%E5%9C%A8%20DRAM%22%5D%0A%20%20V%20--%3E%20SHARE%7B%22%E8%A2%AB%20block%20%E5%86%85%E5%A4%9A%E7%BA%BF%E7%A8%8B%E5%A4%8D%E7%94%A8%3F%22%7D%0A%20%20SHARE%20--%3E%7C%22%E6%98%AF%22%7C%20SMEM%5B%22%E6%8B%B7%E8%BF%9B%20smem%20%E5%A4%8D%E7%94%A8%22%5D%0A%20%20SHARE%20--%3E%7C%22%E5%90%A6%20%E5%81%B6%E5%B0%94%E8%AF%BB%22%7C%20GLB%5B%22%E7%95%99%E5%9C%A8%20HBM%20%E8%B5%B0%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>bank 冲突留给下一课——smem 的并行度还剩最后一条账。张量核的喂料路径（smem 布局与碎片对齐）是第五课的合同。本课的数字随代际漂移：L2 多大、HBM 几代，每两年一换；漂移的是数字，不漂移的是相邻层一至两个量级的价差与「先复用、再合并、后占用」的顺序。跨 SM 的数据流（peer 直访、NVLink）不在本课，那是多卡系统的题。</p><p><span class="marginnote">一次真实的误诊：核函数 L2 命中率不低、DRAM 吞吐却顶满——查出来是一个中间张量每步从 HBM 重读，而它的复用半径只有一个 block。挪进 smem 后 DRAM 吞吐降一半，核反而快了：省下来的带宽让别的 warp 不用等。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>层次账先于代码：寄存器零等待、smem/L1 片上 192 KB、L2 40 MB、HBM 约 2 TB/s，相邻层差量级。</li><li>溢出的 local 名字骗人：实体在 DRAM，寄存器压力最后都变成带宽账。</li><li>合并判据看 warp 的地址分布：连续 128 字节一个事务；stride 每大一步，扇区利用率按比例掉。</li><li>smem 与 L1 同一块 SRAM，分账是启动配置——划多少是核函数的决策。</li><li>决策顺序固定：复用、合并、占用率；顺序反了会在错误的层上找带宽。</li><li>出处：Kirk &amp; Hwu, <em>Programming Massively Parallel Processors</em>；NVIDIA CUDA C++ Programming Guide 内存层次章；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',5))])}const M=i(n,[["render",c]]);export{u as __pageData,M as default};
